content:
{
  "book_code": "2ES",
  "verses": [
    {
      "chapter": 1,
      "verse": 21,
      "text_ar": "قاسمتُكم أراضٍ خصبة، وطَرَدتُ أمامَكم القنانيِّينَ والفِرازِيِّينَ والفِلسطِيِّين. ماذا أُزيِدُ عليكُم؟» قالَ الرَّبُّ.",
      "review_notes_ar": []
    },
    {
      "chapter": 1,
      "verse": 22,
      "text_ar": "قالَ الرَّبُّ القَدِير: «لمَّا كنتُم في البرِّيَّةِ عندَ جدولِ المرارة، ومِنَ العَطَشِ تَضرَّعتم وسَبًتُم اسَّمي،",
      "review_notes_ar": []
    },
    {
      "chapter": 1,
      "verse": 23,
      "text_ar": "لم أعطِكُم ناراً على سَبَيتِكم، بل ألقَيتُ في الماءِ شَجرةً فجَعَلتُ النهرَ حَليفاً.",
      "review_notes_ar": []
    },
    {
      "chapter": 1,
      "verse": 24,
      "text_ar": "ماذا أُصنِعُ بك يا يَعقوب؟ أنتَ يَهُودا لم تَسمَع لَنا. سأَلتفِتُ إلى أمَمٍ أُخرى وأُعطيها اسَّمي، فيُحافِظون على فَرَائِضي.",
      "review_notes_ar": []
    },
    {
      "chapter": 1,
      "verse": 25,
      "text_ar": "إذ هَجرَتموني هَجَرتُكم أيضاً. وإذا ادَّعَيتُم عليَّ ضَنَاني لن أردَ إكراماً لكُم.",
      "review_notes_ar": []
    },
    {
      "chapter": 1,
      "verse": 26,
      "text_ar": "إذا عَظَمتُمُ عليَّ لن أنصتَ، لأنَّ أيديَكم ملطَّخةٌ بالدمِ وقَدَماكم سَريعةٌ إلى الذِّبَح.",
      "review_notes_ar": []
    },
    {
      "chapter": 1,
      "verse": 27,
      "text_ar": "ليس كأنَّكم هَجَرتُموني بلَ لأنفسِكم» قالَ الرَّبُّ.",
      "review_notes_ar": []
    },
    {
      "chapter": 1,
      "verse": 28,
      "text_ar": "قالَ الرَّبُّ القَدِير: «أما تذكَّرتُم كيف أخاطبُكم كالأبِ إلى ابنَتهِ وكإلأمِّ إلى بنِيها، وكالمُرضِعةِ إلى رُضيعيها،",
      "review_notes_ar": []
    },
    {
      "chapter": 1,
      "verse": 29,
      "text_ar": "لكي تكونوا لي شَعباً وكَونَ لي إلهاً، وتكونوا لي بنينَ ويَكونَ لي أباً؟\"",
      "review_notes_ar": []
    },
    {
      "chapter": 1,
      "verse": 30,
      "text_ar": "جمعتُكم كالدِّجّةِ تحتَ جناحيها. الآنَ ماذا أُستطيعُ أن أصنَعَ لكم؟ سَوطُقُكم مِن قِبَلي.",
      "review_notes_ar": []
    },
    {
      "chapter": 1,
      "verse": 31,
      "text_ar": "إذا ذبَحتُم لي ذَبائحَ سأَصرِفُ وجهي عنكُم، لأنَّي رَفضتُ أعيادَكُم وعرائصَكم وأذكيَتَكم.",
      "review_notes_ar": []
    },
    {
      "chapter": 1,
      "verse": 32,
      "text_ar": "أرسَلتُ إليكم عبادي الأنبياءَ، فذبحتُموهم وقطَّعتُم أجسادَهم، ودَماً سألُّه منكم» قالَ الرَّبُّ.",
      "review_notes_ar": []
    },
    {
      "chapter": 1,
      "verse": 33,
      "text_ar": "قالَ الرَّبُّ القَدِير: «بيتُكم خَرب. سأَطرَدُكم كسَوفِه النِّسبِ بالرياح.",
      "review_notes_ar": []
    },
    {
      "chapter": 1,
      "verse": 34,
      "text_ar": "بَنيكُم لن يُثمِروا لأنَّهم تَراهَوا واجَروا بِرِّي فَعلوا الشَّرَّ أمامي.",
      "review_notes_ar": []
    },
    {
      "chapter": 1,
      "verse": 35,
      "text_ar": "أُعطي بَيتَكُم لذينَ يَأتون، وأما لم يَسمَعوا اسمي فَسَيبطلون عَليَّ. والذينَ لم يروا آياتي فَسَيفعلون ما أمرتُ بهم.",
      "review_notes_ar": []
    },
    {
      "chapter": 1,
      "verse": 36,
      "text_ar": "لم يروا الأنبياء، ولِكنّهُم سيَذكِرون حالَهم الأولة.",
      "review_notes_ar": []
    },
    {
      "chapter": 1,
      "verse": 37,
      "text_ar": "أَدعو شاهِداً على سَوفَ الشَّكوى الدِّينِ، ونَقلَ ابنائِها بفرحٍ. مع أنَّهم لا يرَونني بأعينِ الجسد، لَكنُّهُم في مُروترِهم سَيبطلون ما أقولُ.",
      "review_notes_ar": []
    },
    {
      "chapter": 1,
      "verse": 38,
      "text_ar": "والآن يا أبي، تَبَصَّر في المَجدِ، وانظُر إليهم الذينَ يَأتونَ من الشِّرَق: هُمُ الذينَ أعطَيتُ لهم.",
      "review_notes_ar": []
    },
    {
      "chapter": 1,
      "verse": 39,
      "text_ar": "أَشامون، إسحاقَ، ويعقوب، هوشاع، عاموس، ومواح، يوئيل، يونس،",
      "review_notes_ar": []
    },
    {
      "chapter": 1,
      "verse": 40,
      "text_ar": "يونان، يَلوم، بَرق، طَحر، وملاخي الذي هو أيضاً يُسمَّى مَرسَلَ الرَّبِّ.",
      "review_notes_ar": []
    }
  ]
}
